 import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, PointLight, ClampToEdgeWrapping, SRGBColorSpace, DoubleSide } = THREE;

  const root = new Group();
  root.name = 'filmstrip-carousel';

  const colors = config?.intent?.visualSpec?.colors ?? config?.colors ?? {};
  const bg = colors.background ?? '#0b0b10';
  const surface = colors.surface ?? '#14141a';
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const gradStops = colors.gradientStops ?? [{ at: 0, hex: bg }, { at: 1, hex: surface }];

  const strip = new Group();
  strip.rotation.y = -18 * (Math.PI / 180);
  root.add(strip);

  const backdropGeo = new PlaneGeometry(8, 7);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  backdropMat.colorNode = mix(color(gradStops[0].hex), color(gradStops[gradStops.length - 1].hex), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const key = new DirectionalLight(paper, 1.2);
  key.position.set(-3, 4, 5);
  root.add(key);

  const rim = new PointLight(accent, 1.0, 25, 2);
  rim.position.set(4, 2, -3);
  root.add(rim);

  const fill = new DirectionalLight(paper, 0.5);
  fill.position.set(0, -2, 4);
  root.add(fill);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline') || items[0];
  const bodyItem = items.find(i => i.role === 'body') || items[1];
  const captionItems = items.filter(i => i.role === 'caption');

  const captionFallbacks = ['NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'];
  while (captionItems.length < captionFallbacks.length) {
    captionItems.push({ text: captionFallbacks[captionItems.length], role: 'caption' });
  }

  const headline = ctx.fontAtlas.createText(headlineItem?.text ?? 'The collection', {
    fontSize: headlineItem?.typography?.fontSize ?? 68,
    color: paper,
    align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const body = ctx.fontAtlas.createText(bodyItem?.text ?? 'Five calibres. One discipline.', {
    fontSize: bodyItem?.typography?.fontSize ?? 26,
    color: paper,
    align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);

  const cardW = 1.6;
  const cardH = 1.0;
  const pitch = 1.85;
  const count = 5;

  const frameGeo = new BoxGeometry(cardW + 0.05, cardH + 0.05, 0.025);
  const frameMat = new MeshPhysicalNodeMaterial({ color: ink, roughness: 0.55, metalness: 0.2, clearcoat: 0.15 });

  const underlineGeo = new PlaneGeometry(cardW, 0.035);
  const underlineMatShared = new MeshStandardNodeMaterial({ color: accent, emissive: accent, emissiveIntensity: 1.3 });
  const photoGeo = new PlaneGeometry(cardW, cardH);

  const cardTints = [0xfff5f0, 0xf0f7ff, 0xfffaf0, 0xf5f5f5, 0xeaf4f4];

  const cards = [];

  for (let i = 0; i < count; i++) {
    const cg = new Group();
    cg.position.x = (i - 2) * pitch;

    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.015;
    cg.add(frame);

    const mat = new MeshPhysicalNodeMaterial({
      color: cardTints[i],
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true
    });
    const photo = new Mesh(photoGeo, mat);
    photo.position.z = 0.015;
    cg.add(photo);

    const underline = new Mesh(underlineGeo, underlineMatShared.clone());
    underline.position.set(0, -cardH / 2 - 0.04, 0.03);
    underline.visible = false;
    cg.add(underline);

    const cap = ctx.fontAtlas.createText(captionItems[i].text, {
      fontSize: captionItems[i]?.typography?.fontSize ?? 18,
      color: paper,
      align: 'center'
    });
    cap.position.set(0, -cardH / 2 - 0.18, 0.03);
    cap.visible = false;
    cg.add(cap);

    strip.add(cg);
    cards.push({ group: cg, photoMat: mat, underline, caption: cap, index: i, baseCropX: i * (1 / count) });
  }

  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png';
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      tex.needsUpdate = true;

      cards.forEach((c, i) => {
        const slice = tex.clone();
        slice.colorSpace = SRGBColorSpace;
        slice.wrapS = ClampToEdgeWrapping;
        slice.wrapT = ClampToEdgeWrapping;
        slice.repeat.set(1 / count, 1);
        slice.offset.set(c.baseCropX, 0);
        slice.needsUpdate = true;

        c.photoMat.map = slice;
        c.tex = slice;
      });
    }).catch(() => {});
  }

  const timelines = [];

  const entrance = gsap.timeline();
  entrance.from(strip.position, { y: -0.4, duration: 0.7, ease: 'power3.out' }, 0);
  entrance.from(strip.scale, { x: 0.9, y: 0.9, z: 0.9, duration: 0.7, ease: 'power3.out' }, 0);
  cards.forEach((c, i) => {
    entrance.from(c.group.position, { y: 0.3, duration: 0.6, ease: 'power2.out' }, 0.1 + i * 0.08);
    entrance.from(c.photoMat, { opacity: 0, duration: 0.5 }, 0.1 + i * 0.08);
  });
  entrance.from([headline, body], { opacity: 0, y: 0.2, duration: 0.5, stagger: 0.1, ease: 'power2.out' }, 0.4);
  timelines.push(entrance);

  let snapping = false;
  let lastX = strip.position.x;
  let idleTime = 0;

  const updateFocus = () => {
    const x = strip.position.x;
    const focusIndex = Math.max(0, Math.min(count - 1, Math.round(-x / pitch) + 2));
    cards.forEach(c => {
      const dist = Math.abs(c.index - focusIndex);
      const opacity = 1 - 0.45 * (dist / (count - 1));
      const isFocus = c.index === focusIndex;
      c.photoMat.opacity = opacity;
      c.group.scale.setScalar(isFocus ? 1.0 : 0.92);
      c.group.rotation.y = isFocus ? 0.314159 : 0;
      c.group.position.z = isFocus ? 0.06 : 0;
      c.underline.visible = isFocus;
      c.caption.visible = isFocus;
    });
    return focusIndex;
  };

  root.onBeforeRender = () => {
    if (entrance.isActive()) return;

    const x = strip.position.x;
    const scroll = x / 0.5;

    cards.forEach(c => {
      if (c.tex) {
        const sign = c.index % 2 === 0 ? 1 : -1;
        const shift = Math.max(-0.04, Math.min(0.04, scroll * 0.04 * sign));
        c.tex.offset.x = c.baseCropX + shift;
      }
    });

    const dx = Math.abs(x - lastX);
    lastX = x;

    if (snapping) return;

    if (dx < 0.0005) {
      idleTime += 0.016;
      if (idleTime > 0.15) {
        const focusIndex = updateFocus();
        const targetX = -(focusIndex - 2) * pitch;
        const dist = Math.abs(targetX - x);

        if (dist > 0.02) {
          snapping = true;
          idleTime = 0;
          const snapTween = gsap.to(strip.position, {
            x: targetX,
            duration: 0.9,
            ease: 'power4.out',
            onComplete: () => {
              snapping = false;
              const focused = cards.find(c => c.index === focusIndex);
              if (focused) {
                const settle = gsap.fromTo(focused.group.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
                timelines.push(settle);
              }
            }
          });
          timelines.push(snapTween);
        } else {
          idleTime = 0;
          updateFocus();
        }
      }
    } else {
      idleTime = 0;
      updateFocus();
    }
  };

  const parallax = ctx.primitives?.['parallax-scroll']?.(strip, { intensity: 0.5 });
  if (parallax?.timeline) timelines.push(parallax.timeline);

  root.userData.handlers = {
    scroll: (delta = 0) => {
      if (snapping) return;
      const target = strip.position.x + delta * 0.5;
      gsap.to(strip.position, { x: target, duration: 0.3, ease: 'power2.out' });
    },
    click: () => {
      const current = updateFocus();
      const next = (current + 1) % count;
      const targetX = -(next - 2) * pitch;
      snapping = true;
